<?php
require_once __DIR__.'/includes/bootstrap.php'; require_login(); $user=current_user();
$requests=db()->prepare("SELECT sr.id,sr.status,l.title AS target_title,ol.title AS offered_title, u.name AS other_name, CASE WHEN sr.requester_id=? THEN sr.owner_id ELSE sr.requester_id END AS other_id FROM swap_requests sr JOIN listings l ON l.id=sr.listing_id LEFT JOIN listings ol ON ol.id=sr.offered_listing_id JOIN users u ON u.id=CASE WHEN sr.requester_id=? THEN sr.owner_id ELSE sr.requester_id END WHERE sr.requester_id=? OR sr.owner_id=? ORDER BY sr.updated_at DESC");
$requests->execute([$user['id'],$user['id'],$user['id'],$user['id']]); $threads=$requests->fetchAll();
$threadId=filter_input(INPUT_GET,'request_id',FILTER_VALIDATE_INT)?: (int)($threads[0]['id']??0); $active=null;
foreach($threads as $t) if((int)$t['id']===$threadId){$active=$t;break;}
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $threadId=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT)?:0; $check=db()->prepare('SELECT id FROM swap_requests WHERE id=? AND (requester_id=? OR owner_id=?)');$check->execute([$threadId,$user['id'],$user['id']]); if(!$check->fetch()) { http_response_code(403); exit('You cannot access this conversation.'); } $action=(string)($_POST['action']??'message'); if($action==='report_dispute'){ $details=trim((string)($_POST['details']??'')); if(mb_strlen($details)<10||mb_strlen($details)>2000)set_flash('error','Describe the issue in 10 to 2,000 characters.');else{$ins=db()->prepare("INSERT INTO disputes(request_id,reported_by,details) VALUES(?,?,?)");$ins->execute([$threadId,$user['id'],$details]);set_flash('success','Your dispute was sent to the admin team.');} } else { $body=trim((string)($_POST['body']??'')); if($body===''||mb_strlen($body)>2000) set_flash('error','Message must be between 1 and 2,000 characters.'); else { $ins=db()->prepare('INSERT INTO messages(request_id,sender_id,body) VALUES(?,?,?)');$ins->execute([$threadId,$user['id'],$body]); } } redirect('chat.php?request_id='.$threadId); }
$messages=[]; if($active){$m=db()->prepare('SELECT m.*,u.name AS sender_name FROM messages m JOIN users u ON u.id=m.sender_id WHERE m.request_id=? ORDER BY m.created_at ASC LIMIT 300');$m->execute([$threadId]);$messages=$m->fetchAll();}
$pageTitle='Messages — ReWear'; require __DIR__.'/includes/header.php'; ?>
<section class="page-hero container"><span class="eyebrow">A GOOD SWAP STARTS WITH A CONVERSATION</span><h1>Your messages.</h1><p>Discuss fit, condition, collection, and shipping before confirming a swap.</p></section><section class="container chat-layout"><div class="chat-panel"><h2 style="font-size:26px">Swap conversations</h2><?php if(!$threads): ?><div class="empty-inline">No conversations yet. Send a swap request from a clothing item to start one.</div><?php else: ?><div class="table-list"><?php foreach($threads as $t): ?><a class="table-row" href="chat.php?request_id=<?= (int)$t['id'] ?>"><div class="table-main"><strong><?= e($t['other_name']) ?> · <?= e($t['target_title']) ?></strong><small>Offering: <?= e($t['offered_title'] ?: 'Discuss in chat') ?></small></div><span class="status status-<?= e($t['status']) ?>"><?= e(ucfirst($t['status'])) ?></span><span>↗</span></a><?php endforeach; ?></div><?php if($active): ?><h3 style="margin-top:25px">Conversation with <?= e($active['other_name']) ?></h3><div class="chat-thread"><?php foreach($messages as $msg): ?><div class="chat-message <?= (int)$msg['sender_id']===(int)$user['id']?'mine':'' ?>"><?= nl2br(e($msg['body'])) ?><small><?= e($msg['sender_name']) ?> · <?= e(date('M j, g:i a',strtotime($msg['created_at']))) ?></small></div><?php endforeach; ?><?php if(!$messages): ?><p class="value-note">No messages yet. Say hello and discuss the exchange.</p><?php endif; ?></div><form method="post" class="chat-form"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="request_id" value="<?= (int)$active['id'] ?>"><input type="hidden" name="action" value="message"><textarea name="body" maxlength="2000" required placeholder="Write a message…"></textarea><button class="btn" type="submit">Send ↗</button></form><details style="margin-top:18px"><summary style="font-size:11px;color:#8a3e35;cursor:pointer">Report a swap problem</summary><form method="post" class="form-stack" style="margin-top:12px"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="request_id" value="<?= (int)$active['id'] ?>"><input type="hidden" name="action" value="report_dispute"><label>What happened?<textarea name="details" required minlength="10" maxlength="2000" placeholder="Describe the issue clearly…"></textarea></label><button class="btn btn-outline" type="submit">Submit report</button></form></details><?php endif; ?><?php endif; ?></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
